import * as React from "react";

export type SpeakerTowerIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SpeakerTowerIcon({ size = 20, ...props }: SpeakerTowerIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="7" y="3.5" width="10" height="17" rx="1.5" /><circle cx="12" cy="8" r="2" /><circle cx="12" cy="15.5" r="3" />
    </svg>
  );
}
